  `art_description` text NOT NULL,
  `art_damage` varchar(20) NOT NULL,
  `cost_red` int DEFAULT '0',
  `cost_blue` int DEFAULT '0',
  `cost_green` int DEFAULT '0',
  `cost_yellow` int DEFAULT '0',
  `cost_purple` int DEFAULT '0',
  `cost_white` int DEFAULT '0',
  `cost_any` int DEFAULT '0',
  `tokkou` enum('RED','BLUE','GREEN','YELLOW','PURPLE','WHITE') DEFAULT NULL,
  `tokkou_damage` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `card_id` (`card_id`),
  CONSTRAINT `card_arts_ibfk_1` FOREIGN KEY (`card_id`) REFERENCES `cards` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=159 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
