INSERT INTO `oshi_cards` VALUES (4,0,1,0,0,0,0,6,'ぽえぽえぽえ～','[ターンに1回]自分のセンターホロメンが〈沙花叉クロヱ〉の時に使える：自分のデッキの上から3枚を見る。そのカードすべてを、アーカイブするか、好きな順でデッキの上に戻す。','[ホロパワー：1消費]','人生リセットボタン','[ゲームに1回]自分の手札を数えて、自分の[手札すべてとアーカイブのホロメンすべて]をデッキに戻してシャッフルする。そして手札からデッキに戻したカード1枚につき、自分のデッキを1枚引く。','[ホロパワー：3消費]'),(16,0,0,0,0,1,0,5,'ゾンビ戦術','[ターンに1回]自分の#ID2期生を持つホロメン1人を、自分のアーカイブのホロメンを使ってBloomさせる。','[ホロパワー：2消費]','蘇るオリー','[ゲームに1回]自分のデッキを4枚引いた後、手札2枚をアーカイブする。その後、自分のホロメン1人を、自分のアーカイブのホロメンを使ってBloomできる。','[ホロパワー：2消費]'),(25,0,1,0,0,0,0,6,'ぽえぽえぽえ～','[ターンに1回]自分のセンターホロメンが〈沙花叉クロヱ〉の時に使える：自分のデッキの上から3枚を見る。そのカードすべてを、アーカイブするか、好きな順でデッキの上に戻す。','[ホロパワー：1消費]','人生リセットボタン','[ゲームに1回]自分の手札を数えて、自分の[手札すべてとアーカイブのホロメンすべて]をデッキに戻してシャッフルする。そして手札からデッキに戻したカード1枚につき、自分のデッキを1枚引く。','[ホロパワー：3消費]'),(31,0,0,0,0,0,1,5,'マスコット創造','[ターンに1回]自分のデッキから、マスコット1枚を公開し、手札に加える。そしてデッキをシャッフルする。','[ホロパワー：2消費]','フブキングダム','[ゲームに1回]自分の白ホロメンが相手のホロメンをダウンさせた時、自分のステージのマスコット2枚につき、サイコロを1回振れる：奇数が1回以上出たなら、相手のライフ-1。','[ホロパワー：2消費]'),(58,1,0,0,0,0,0,5,'Ahoy!','[ターンに1回]自分のこのターンにBloomした#3期生を持つホロメン1人を、自分の手札のホロメンを使ってもう1回Bloomさせる。','[ホロパワー：3消費]','出航～！','[ゲームに1回]相手のセンターホロメンかコラボホロメンどちらかに、自分のセンターホロメンの〈宝鐘マリン〉に重なっているホロメン1枚につき、特殊ダメージ50を与える。','[ホロパワー：2消費]'),(70,0,0,0,0,0,1,5,'マスコット創造','[ターンに1回]自分のデッキから、マスコット1枚を公開し、手札に加える。そしてデッキをシャッフルする。','[ホロパワー：2消費]','フブキングダム','[ゲームに1回]自分の白ホロメンが相手のホロメンをダウンさせた時、自分のステージのマスコット2枚につき、サイコロを1回振れる：奇数が1回以上出たなら、相手のライフ-1。','[ホロパワー：2消費]'),(82,1,0,0,0,0,0,5,'Ahoy!','[ターンに1回]自分のこのターンにBloomした#3期生を持つホロメン1人を、自分の手札のホロメンを使ってもう1回Bloomさせる。','[ホロパワー：3消費]','出航～！','[ゲームに1回]相手のセンターホロメンかコラボホロメンどちらかに、自分のセンターホロメンの〈宝鐘マリン〉に重なっているホロメン1枚につき、特殊ダメージ50を与える。','[ホロパワー：2消費]'),(97,0,0,0,0,1,0,5,'ゾンビ戦術','[ターンに1回]自分の#ID2期生を持つホロメン1人を、自分のアーカイブのホロメンを使ってBloomさせる。','[ホロパワー：2消費]','蘇るオリー','[ゲームに1回]自分のデッキを4枚引いた後、手札2枚をアーカイブする。その後、自分のホロメン1人を、自分のアーカイブのホロメンを使ってBloomできる。','[ホロパワー：2消費]'),(109,0,0,0,0,1,0,5,'ねえ゛え゛え゛え゛え゛え゛え゛','[ターンに1回]自分の〈紫咲シオン〉の能力でサイコロを振った時に使える：サイコロを1回振り直す。','[ホロパワー：1消費]','シオンのすごい魔法','[ゲームに1回]自分の紫センターホロメンがアーツを使った時に使える：相手のセンターホロメンに、相手のセンターホロメンのエール1枚につき、特殊ダメージ50を与える。','[ホロパワー：2消費]'),(114,0,0,0,0,1,0,5,'ねえ゛え゛え゛え゛え゛え゛え゛','[ターンに1回]自分の〈紫咲シオン〉の能力でサイコロを振った時に使える：サイコロを1回振り直す。','[ホロパワー：1消費]','シオンのすごい魔法','[ゲームに1回]自分の紫センターホロメンがアーツを使った時に使える：相手のセンターホロメンに、相手のセンターホロメンのエール1枚につき、特殊ダメージ50を与える。','[ホロパワー：2消費]'),(123,0,0,1,0,0,0,5,'HALU','[ターンに1回]自分のホロメンの緑エール1枚をアーカイブすることで、自分のエールデッキから、エール1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。','[ホロパワー：2消費]','極彩色の宴','[ゲームに1回]このターンの間、自分のステージの#ID2期生を持つホロメン全員は、そのホロメンのエール1色につき、アーツ+20。','[ホロパワー：2消費]'),(129,1,0,0,0,0,0,5,'Ahoy!','[ターンに1回]自分のこのターンにBloomした#3期生を持つホロメン1人を、自分の手札のホロメンを使ってもう1回Bloomさせる。','[ホロパワー：3消費]','出航～！','[ゲームに1回]相手のセンターホロメンかコラボホロメンどちらかに、自分のセンターホロメンの〈宝鐘マリン〉に重なっているホロメン1枚につき、特殊ダメージ50を与える。','[ホロパワー：2消費]'),(157,0,0,0,0,1,0,5,'サンプリング','[ターンに1回]自分の手札2枚をアーカイブすることで、アーカイブの#ENを持つホロメン2枚を手札に戻す。','[ホロパワー：2消費]','死神ラップ','[ゲームに1回]自分のセンターホロメンが〈森カリオペ〉の時に使える：このターンの間、自分の〈森カリオペ〉1人は、アーツを使った後、同じアーツをもう1回使う。','[ホロパワー：2消費]'),(166,0,0,0,0,1,0,5,'サンプリング','[ターンに1回]自分の手札2枚をアーカイブすることで、アーカイブの#ENを持つホロメン2枚を手札に戻す。','[ホロパワー：2消費]','死神ラップ','[ゲームに1回]自分のセンターホロメンが〈森カリオペ〉の時に使える：このターンの間、自分の〈森カリオペ〉1人は、アーツを使った後、同じアーツをもう1回使う。','[ホロパワー：2消費]'),(186,0,1,0,0,0,0,6,'ぽえぽえぽえ～','[ターンに1回]自分のセンターホロメンが〈沙花叉クロヱ〉の時に使える：自分のデッキの上から3枚を見る。そのカードすべてを、アーカイブするか、好きな順でデッキの上に戻す。','[ホロパワー：1消費]','人生リセットボタン','[ゲームに1回]自分の手札を数えて、自分の[手札すべてとアーカイブのホロメンすべて]をデッキに戻してシャッフルする。そして手札からデッキに戻したカード1枚につき、自分のデッキを1枚引く。','[ホロパワー：3消費]'),(199,0,0,0,0,0,1,5,'マスコット創造','[ターンに1回]自分のデッキから、マスコット1枚を公開し、手札に加える。そしてデッキをシャッフルする。','[ホロパワー：2消費]','フブキングダム','[ゲームに1回]自分の白ホロメンが相手のホロメンをダウンさせた時、自分のステージのマスコット2枚につき、サイコロを1回振れる：奇数が1回以上出たなら、相手のライフ-1。','[ホロパワー：2消費]'),(207,0,0,1,0,0,0,5,'HALU','[ターンに1回]自分のホロメンの緑エール1枚をアーカイブすることで、自分のエールデッキから、エール1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。','[ホロパワー：2消費]','極彩色の宴','[ゲームに1回]このターンの間、自分のステージの#ID2期生を持つホロメン全員は、そのホロメンのエール1色につき、アーツ+20。','[ホロパワー：2消費]');
